const BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:8000";

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, options);
  if (!res.ok) {
    const err = await res.json().catch(() => ({ detail: "Unknown error" }));
    throw new Error(err.detail || `HTTP ${res.status}`);
  }
  return res.json();
}

// Upload
export async function uploadFile(file, distributorName) {
  const form = new FormData();
  form.append("file", file);
  if (distributorName) form.append("distributor_name", distributorName);
  return request("/upload", { method: "POST", body: form });
}

// Uploads history
export async function getUploads() {
  return request("/uploads");
}

export async function getUploadById(uploadId) {
  return request(`/uploads/${uploadId}`);
}

// Distributors
export async function getDistributors() {
  return request("/distributors");
}

// Analytics
export async function getOverview(params = {}) {
  const qs = new URLSearchParams(params).toString();
  return request(`/analytics/overview${qs ? "?" + qs : ""}`);
}

export async function getShops(params = {}) {
  const qs = new URLSearchParams(params).toString();
  return request(`/analytics/shops${qs ? "?" + qs : ""}`);
}

export async function getMoMTrend(params = {}) {
  const qs = new URLSearchParams(params).toString();
  return request(`/analytics/mom-trend${qs ? "?" + qs : ""}`);
}

export async function getTopShops(params = {}) {
  const qs = new URLSearchParams(params).toString();
  return request(`/analytics/top-shops${qs ? "?" + qs : ""}`);
}

// Export
export function getExcelExportUrl(params = {}) {
  const qs = new URLSearchParams(params).toString();
  return `${BASE_URL}/export/excel${qs ? "?" + qs : ""}`;
}
